examples.template:
VStack(alignment: .leading, spacing: 12) {
    Text({{label}}).monarchTextStyle(.label)
    Toggle(isOn: Binding(get: { selected == {{options.0.value}} }, set: { if $0 { selected = {{options.0.value}} } })) {
        VStack(alignment: .leading, spacing: 2) {
            Text({{options.0.label}}).monarchTextStyle(.body)
            Text({{options.0.description}}).monarchTextStyle(.caption)
                .foregroundStyle(theme.colors.textMuted)
        }
    }
    .toggleStyle(.monarchRadio)
    Toggle(isOn: Binding(get: { selected == {{options.1.value}} }, set: { if $0 { selected = {{options.1.value}} } })) {
        VStack(alignment: .leading, spacing: 2) {
            Text({{options.1.label}}).monarchTextStyle(.body)
            Text({{options.1.description}}).monarchTextStyle(.caption)
                .foregroundStyle(theme.colors.textMuted)
        }
    }
    .toggleStyle(.monarchRadio)
    Toggle(isOn: Binding(get: { selected == {{options.2.value}} }, set: { if $0 { selected = {{options.2.value}} } })) {
        VStack(alignment: .leading, spacing: 2) {
            Text({{options.2.label}}).monarchTextStyle(.body)
            Text({{options.2.description}}).monarchTextStyle(.caption)
                .foregroundStyle(theme.colors.textMuted)
        }
    }
    .toggleStyle(.monarchRadio)
    .disabled({{options.2.disabled}})
}

examples.code:
VStack(alignment: .leading, spacing: 12) {
    Text("Workspace visibility").monarchTextStyle(.label)
    Toggle(isOn: Binding(get: { selected == "members" }, set: { if $0 { selected = "members" } })) {
        VStack(alignment: .leading, spacing: 2) {
            Text("Members only").monarchTextStyle(.body)
            Text("Only people you invite can see this workspace.").monarchTextStyle(.caption)
                .foregroundStyle(theme.colors.textMuted)
        }
    }
    .toggleStyle(.monarchRadio)
    Toggle(isOn: Binding(get: { selected == "organization" }, set: { if $0 { selected = "organization" } })) {
        VStack(alignment: .leading, spacing: 2) {
            Text("Whole organization").monarchTextStyle(.body)
            Text("Anyone in your organization can find and join it.").monarchTextStyle(.caption)
                .foregroundStyle(theme.colors.textMuted)
        }
    }
    .toggleStyle(.monarchRadio)
    Toggle(isOn: Binding(get: { selected == "public" }, set: { if $0 { selected = "public" } })) {
        VStack(alignment: .leading, spacing: 2) {
            Text("Public link").monarchTextStyle(.body)
            Text("Anyone with the link can view it.").monarchTextStyle(.caption)
                .foregroundStyle(theme.colors.textMuted)
        }
    }
    .toggleStyle(.monarchRadio)
    .disabled(true)
}
